 again", "devil put aside", "demon put aside"], "new": ["demon put aside", "devil put aside", "devil left behind"]}, {"slug": "bohemian-rhapsody", "mode": "hell", "number": 43, "old": ["stone me", "stone you", "own me"], "new": ["stone me", "own me", "stop me"]}, {"slug": "bohemian-rhapsody", "mode": "hell", "number": 44, "old": ["look in my eye", "spit in my again", "spit in my eye"], "new": ["look in my eye", "spit in my face", "spit in my eye"]}, {"slug": "bohemian-rhapsody", "mode": "hell", "number": 47, "old": ["get right outta again", "run right outta here", "get right outta here"], "new": ["run right outta here", "get far outta here", "get right outta here"]}, {"slug": "bohemian-rhapsody", "mode": "hell", "number": 50, "old": ["wind goes", "rain blows", "wind blows"], "new": ["wind goes", "rain falls", "wind blows"]}], "versions": [{"mode": "standard", "old": 1, "new": 2}, {"mode": "medium", "old": 1, "new": 2}, {"mode": "hard", "old": 1, "new": 2}, {"mode": "hell", "old": 1, "new": 2}], "descriptions": [{"slug": "lea", "old": "《Lea》描寫一段充滿深情、依戀與不安的愛情。歌中的主角曾經毫無保留地付出真心，將所有的愛與希望寄託在 Lea 身上，相信她是生命中無可取代的人。然而，隨著兩人的關係逐漸變得不明朗，他開始懷疑自己的感情是否仍被珍惜，也不知道對方是否還願意接受這份愛。他試圖忽略外界的質疑，卻始終無法消除內心的不安。歌曲反覆詢問 Lea 是否仍希望自己繼續愛著她，流露出深深的眷戀與渴望。最終，《Lea》傳達的是愛情中的忠誠、脆弱與不確定：即使心中的愛意從未改變，當對方的心意變得模糊，最令人難", "new": "《Lea》描寫一段充滿深情、依戀與不安的愛情。歌中的主角曾經毫無保留地付出真心，將所有的愛與希望寄託在 Lea 身上，相信她是生命中無可取代的人。然而，隨著兩人的關係逐漸變得不明朗，他開始懷疑自己的感情是否仍被珍惜，也不知道對方是否還願意接受這份愛。他試圖忽略外界的質疑，卻始終無法消除內心的不安。歌曲反覆詢問 Lea 是否仍希望自己繼續愛著她，流露出深深的眷戀與渴望。最終，《Lea》傳達的是愛情中的忠誠、脆弱與不確定：即使心中的愛意從未改變，當對方的心意變得模糊，最令人難受的，是無法確定這份愛是否仍被需要。"}, {"slug": "dont-stop-believin", "old": "《Don't Stop Believin'》描寫平凡人在孤獨與現實壓力中，仍然努力追尋夢想與希望的故事。歌曲以一位小鎮女孩和一位城市男孩為開端，兩人搭上午夜列車，象徵離開熟悉的生活，勇敢尋找新的可能。街燈下的陌生人各自追求愛情、快樂與人生的意義，即使前路充滿未知，也不願放棄。歌詞亦提醒我們，人生有成功也有失敗，但每個人都有機會改變自己的命運。最終，《Don't StopBelievin'》傳達的是希望、勇氣與堅持：無論生活多麼艱難，都應相信未來，緊緊抓住心中的夢想，永不放棄。", "new": "《Don't Stop Believin'》描寫平凡人在孤獨與現實壓力中，仍然努力追尋夢想與希望的故事。歌曲以一位小鎮女孩和一位城市男孩為開端，兩人搭上午夜列車，象徵離開熟悉的生活，勇敢尋找新的可能。街燈下的陌生人各自追求愛情、快樂與人生的意義，即使前路充滿未知，也不願放棄。歌詞亦提醒我們，人生有成功也有失敗，但每個人都有機會改變自己的命運。最終，《Don't Stop Believin'》傳達的是希望、勇氣與堅持：無論生活多麼艱難，都應相信未來，緊緊抓住心中的夢想，永不放棄。"}, {"slug": "fly-me-to-the-moon", "old": "《Fly Me To The Moon》描寫一份充滿浪漫、幻想與甜蜜的真摯愛情。歌中的主角以飛向月球、漫遊星空作為比喻，表達戀愛時內心的喜悅與興奮，彷彿整個宇宙都因為心愛的人而變得更加美麗。他渴望與對方牽手、親吻，享受兩人相處的幸福時光，也希望這份愛能永遠延續。雖然歌詞充滿天馬行空的想像，但他真正想表達的，其實只是簡單而深刻的愛意。最終，《Fly Me To TheMoon》傳達的是愛情中的浪漫、真誠與幸福：真正動人的愛不一定需要華麗的言語，有時一句簡單的「我愛你」，便足以表達心中最深厚的感情。", "new": "《Fly Me To The Moon》描寫一份充滿浪漫、幻想與甜蜜的真摯愛情。歌中的主角以飛向月球、漫遊星空作為比喻，表達戀愛時內心的喜悅與興奮，彷彿整個宇宙都因為心愛的人而變得更加美麗。他渴望與對方牽手、親吻，享受兩人相處的幸福時光，也希望這份愛能永遠延續。雖然歌詞充滿天馬行空的想像，但他真正想表達的，其實只是簡單而深刻的愛意。最終，《Fly Me To The Moon》傳達的是愛情中的浪漫、真誠與幸福：真正動人的愛不一定需要華麗的言語，有時一句簡單的「我愛你」，便足以表達心中最深厚的感情。"}, {"slug": "with-or-without-you", "old": "《With Or Without You》描寫一段充滿矛盾、痛苦與依戀的愛情。歌中的主角深愛著對方，卻在這段關係中感到無助與疲憊。即使兩人曾經共同度過困難，彼此的付出仍然無法滿足內心的渴望，令感情逐漸變成一種折磨。他想要離開，卻又無法真正放下，陷入在一起會痛苦、分開也會難過的兩難處境。歌曲中的「With Or Without You」正象徵這種無法擺脫的情感掙扎。最終，《With OrWithout You》傳達的是愛情中的依賴、無奈與內心衝突：有時即使深愛一個人，也不代表彼此能夠幸福，而真正困難的，往往是學會面對愛與放手之間的抉擇。", "new": "《With Or Without You》描寫一段充滿矛盾、痛苦與依戀的愛情。歌中的主角深愛著對方，卻在這段關係中感到無助與疲憊。即使兩人曾經共同度過困難，彼此的付出仍然無法滿足內心的渴望，令感情逐漸變成一種折磨。他想要離開，卻又無法真正放下，陷入在一起會痛苦、分開也會難過的兩難處境。歌曲中的「With Or Without You」正象徵這種無法擺脫的情感掙扎。最終，《With Or Without You》傳達的是愛情中的依賴、無奈與內心衝突：有時即使深愛一個人，也不代表彼此能夠幸福，而真正困難的，往往是學會面對愛與放手之間的抉擇。"}, {"slug": "you-give-love-a-bad-name", "old": "《You Give Love a Bad Name》描寫一段充滿誘惑、欺騙與背叛的愛情。歌中的主角曾經被對方天使般的笑容深深吸引，相信她能帶來幸福，卻發現那些甜蜜的承諾背後隱藏著謊言與傷害。他原本真心投入這段感情，對方卻將愛情當成遊戲，令他深陷其中，難以逃脫。歌曲以槍彈、枷鎖、天堂與地獄等強烈意象，表達愛情從美好變成痛苦的巨大反差。最終，《You Give Love a BadName》傳達的是愛情中的背叛、憤怒與失望：當真心遭到玩弄，曾經令人嚮往的愛情也可能變成傷害自己的牢籠，而那些虛假的承諾，更會讓人逐漸失去對愛情的信任。", "new": "《You Give Love a Bad Name》描寫一段充滿誘惑、欺騙與背叛的愛情。歌中的主角曾經被對方天使般的笑容深深吸引，相信她能帶來幸福，卻發現那些甜蜜的承諾背後隱藏著謊言與傷害。他原本真心投入這段感情，對方卻將愛情當成遊戲，令他深陷其中，難以逃脫。歌曲以槍彈、枷鎖、天堂與地獄等強烈意象，表達愛情從美好變成痛苦的巨大反差。最終，《You Give Love a Bad Name》傳達的是愛情中的背叛、憤怒與失望：當真心遭到玩弄，曾經令人嚮往的愛情也可能變成傷害自己的牢籠，而那些虛假的承諾，更會讓人逐漸失去對愛情的信任。"}]}$data$::jsonb; ex jsonb; change jsonb; mi int; qi int; current_options jsonb; sid uuid; before_text text;
begin
select id,exercises into strict sid,ex from public.song_appreciation_songs where slug='bohemian-rhapsody' for update;
for change in select value from jsonb_array_elements(changes->'questions') loop
 select (m.ordinality-1)::int,(q.ordinality-1)::int,q.value->'options' into strict mi,qi,current_options from jsonb_array_elements(ex) with ordinality m,jsonb_array_elements(m.value->'questions') with ordinality q where m.value->>'id'=change->>'mode' and q.value->>'number'=change->>'number';
 if current_options<>change->'old' then raise exception 'Concurrent option change Q%',change->>'number';end if;
 ex:=jsonb_set(ex,array[mi::text,'questions',qi::text,'options'],change->'new');
end loop;
for change in select value from jsonb_array_elements(changes->'versions') loop
 select (ordinality-1)::int into strict mi from jsonb_array_elements(ex) with ordinality where value->>'id'=change->>'mode' and value->'version'=change->'old';
 ex:=jsonb_set(ex,array[mi::text,'version'],change->'new');
end loop;
update public.song_appreciation_songs set exercises=ex,updated_at=now() where id=sid;
for change in select value from jsonb_array_elements(changes->'descriptions') loop
 select description into strict before_text from public.song_appreciation_songs where slug=change->>'slug' for update;
 if before_text<>change->>'old' then raise exception 'Concurrent description change %',change->>'slug';end if;
 update public.song_appreciation_songs set description=change->>'new',updated_at=now() where slug=change->>'slug';
end loop;end $repair$;

create or replace function public.song_editorial_guard() returns trigger language plpgsql set search_path=public as $$
declare m jsonb; q jsonb; option_text text; clean text; rejected jsonb := $bad$["Body's again", "Body'ss aching", "Carry again", "Doesn't really again", "I've stayt to go", "I'ves got to go", "Little high, little again", "Pulled my again", "Thunderbolt and again", "against his again", "back again tonight", "devil put again", "don'ts wanna die", "get right outta again", "he's again", "he'ss dead", "just again", "justs begun", "killed a again", "make you again", "my time has again", "mys time has come", "never been again", "nevers been born", "poor again", "shivers down my again", "spit in my again", "this time again", "thiss time tomorrow", "thrown it all again"]$bad$::jsonb;
begin
if new.published then
 clean:=btrim(regexp_replace(replace(coalesce(new.description,''),'&nbsp;',' '),'<[^>]*>','','g'));
 if clean !~ '[。！？.!?][」』”"’'')）]*$' then raise exception 'Introduction appears unfinished; review the complete final sentence before publishing.' using errcode='23514';end if;
end if;
for m in select value from jsonb_array_elements(new.exercises) loop
 for q in select value from jsonb_array_elements(m->'questions') loop
  for option_text in select lower(replace(value,'’',chr(39))) from jsonb_array_elements_text(q->'options') loop
   if exists(select 1 from jsonb_array_elements_text(rejected) where lower(value)=option_text)
    or option_text ~ '\m(thiss|stayt|justs|nevers|mys)\M'
    or option_text ~ '\m[a-z]+''(ss|ves|res|ms|lls|ds|ts)\M'
   then raise exception 'Malformed listening distractor: % / % Q%. Use real words and an audible contrast.',new.slug,m->>'id',q->>'number' using errcode='23514';end if;
  end loop;
 end loop;
end loop;return new;end $$;
create trigger song_editorial_before_save before insert or update of exercises,description,published on public.song_appreciation_songs for each row execute function public.song_editorial_guard();
